// Post-process and ensure clean JSON response
const input = $json;
let parsed = {};
try {
  if (typeof input.output === 'string') {
    const match = input.output.match(/\{[\s\S]*\}/);
    parsed = match ? JSON.parse(match[0]) : { agent_message: input.output, is_ready_to_save: false };
  } else {
    parsed = input.output || input;
  }
} catch (e) {
  parsed = {
    agent_message: input.output || "Could you please clarify the bill amount and who paid?",
    is_ready_to_save: false
  };
}

return { json: parsed };
